    # Solve using Cramer's rule
    det = a1 * b2 - a2 * b1
    if det == 0:
        # No unique solution (should not happen per problem statement)
        return

    x = (c1 * b2 - c2 * b1) / det
    y = (a1 * c2 - a2 * c1) / det

    # Output as integers
