def parse_equation(eq):
    # Remove whitespace
    eq = eq.replace(" ", "")
    # Handle signs
    if eq.startswith("-"):
        eq = "-1*" + eq[1:]
    elif eq.startswith("+"):
        eq = "1*" + eq[1:]

    # Find x and y terms
    x_term = None
    y_term = None
    for term in eq.split("+"):
        term = term.strip()
        if term.startswith("-"):
            term = "-1*" + term[1:]
        if term.startswith("x"):
            x_term = term
        elif term.startswith("y"):
            y_term = term

    # Extract coefficients
    def extract_coeff(term):
        if term.startswith("-"):
            term = "-1*" + term[1:]
        elif term.startswith("+"):
            term = "1*" + term[1:]
        if term.startswith("x"):
            return int(term[1:])
        elif term.startswith("y"):
            return int(term[1:])
        else:
            return int(term)

    a = extract_coeff(x_term) if x_term else 0
    b = extract_coeff(y_term) if y_term else 0
    c = -a * 1 - b * 1  # Since x + y = c, we can derive c from the equation

    return a, b, c

if __name__ == "__main__":
    solve()
